/**
 * Baseline-condition counterpart turn.
 *
 * The participant believes this is another Prolific participant. The response
 * is generated by a controlled LLM playing an ostensible human (Design §3,
 * §15 P1).
 *
 * Runs server-side so the API key and system prompt never reach the client.
 */

import { NextResponse } from "next/server";
import { generateAction } from "@/lib/ai/client";
import { validateAction } from "@/lib/ai/validator";
import { counterpartStep, type DecidedAction } from "@/lib/negotiation/machine";
import { counterRequirementIssue, getTask, requirementIssue } from "@/lib/tasks";
import type {
  NegotiationTask,
  Package,
  Role,
  StageId,
  TaskId,
} from "@/lib/types";

export const runtime = "nodejs";

interface RequestBody {
  taskId: TaskId;
  /** The participant's role; the counterpart plays the opposite one. */
  participantRole: Role;
  history: Array<{ role: "assistant" | "user"; content: string }>;
  /** Which of the five stages this reply belongs to. */
  stage: StageId;
  /** The package the participant just put on the table, if any. */
  incoming?: Package | null;
  /** The counterpart's own last package, so concessions accumulate. */
  lastCounterpartPackage?: Package | null;
  /**
   * Has the participant voiced any reason for their requirement yet?
   *
   * Decided by the client from the structured attachment log, never by the
   * model reading the text (Design §4 판정 주체). The reason-linked acceptance
   * rule needs a deterministic answer, and asking a model to grade an argument
   * would hand the judgement back to it.
   */
  reasonGiven?: boolean;
  reasonAlreadyRequested?: boolean;
  /**
   * Seconds left on the ten-minute clock.
   *
   * The counterpart reads it: a low clock is what makes it offer to settle on
   * what is already on the table rather than keep trading (Design §4 "Soft
   * close"). Without it the server's decision and the client's disagreed — the
   * client coded an impasse while the model was still writing as though there
   * were time.
   */
  secondsRemaining?: number;
  /**
   * True in the direct conversation that follows a Proxy exchange, where the
   * counterpart has already opened, stated its priority and challenged through
   * its own proxy.
   */
  afterProxy?: boolean;
}

/**
 * What the counterpart says when the model's wording was blocked.
 *
 * In this condition the counterpart is presented as another participant, so
 * the fallback has to sound like one — short, lowercase, and stating the
 * position rather than reciting it. A message that reads like a system notice
 * would be its own tell.
 */
function fallbackText(
  task: NegotiationTask,
  action: DecidedAction,
  proposal: Package | null,
): string {
  if (action === "challenge") return "could we look at bringing that one down a bit?";
  if (action === "request_reason")
    return "can I ask why that one matters so much on your side?";
  if (action === "impasse")
    return "I don't think we're going to get there on these terms.";
  if (!proposal) return "let me think about that and come back to you.";
  const terms = task.issues
    .map((i) => i.options.find((o) => o.id === proposal[i.id])?.label)
    .filter(Boolean)
    .join(", ");
  return `where I am right now: ${terms}.`;
}

export async function POST(request: Request) {
  let body: RequestBody;
  try {
    body = (await request.json()) as RequestBody;
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const task = getTask(body.taskId);
  if (!task) {
    return NextResponse.json({ error: "Unknown task" }, { status: 400 });
  }

  const counterpartRole: Role =
    body.participantRole === "leader" ? "member" : "leader";

  const stage = ([1, 2, 3, 4, 5] as StageId[]).includes(body.stage)
    ? body.stage
    : 1;

  // The state machine decides the move; the model only says it. That split is
  // what makes this counterpart the same for every participant, which is why
  // the design does not need to randomize outcomes: identical behaviour
  // already produces identical results.
  const decision = counterpartStep(
    task,
    counterpartRole,
    stage,
    body.incoming ?? null,
    body.lastCounterpartPackage ?? null,
    {
      reasonGivenForRequirement: body.reasonGiven ?? true,
      reasonAlreadyRequested: body.reasonAlreadyRequested ?? false,
      secondsRemaining: body.secondsRemaining,
    },
  );

  // WHO CHALLENGES WHOM. Design §4 stage 3 has BOTH sides ask the other to
  // lower its requirement, once each, in fixed wording. The counterpart's
  // challenge therefore names the PARTICIPANT'S requirement — and the task
  // stores the challenge keyed by the role being challenged, so this reads it
  // by `participantRole`.
  //
  // Sending it keyed the other way had a Member-counterpart arguing against
  // its own requirement, which left the participant responding to a
  // requirement nobody had advocated.
  const theirRequirement = requirementIssue(task, counterpartRole);
  const yourRequirement = counterRequirementIssue(task, counterpartRole);
  const challenge = task.standardizedChallenge[body.participantRole];

  const decidedAction = ((): string => {
    switch (decision.action) {
      case "open":
        return "Open with your own best package on both terms, and say which one matters most to you.";
      case "state_priority":
        return `Say that ${theirRequirement.label.toLowerCase()} is the term that matters most to you, with one reason about the work. Ask which term matters most to them.`;
      case "challenge":
        return `Send exactly this challenge, in your own words: "${challenge}"`;
      case "request_reason":
        // The reason requirement, in the counterpart's voice. It asks rather
        // than refuses, because Design §4 defers judgement by one turn instead
        // of rejecting outright.
        return `Ask them why ${yourRequirement.label.toLowerCase()} matters so much to them. Make no new offer this turn and do not agree to anything yet.`;
      case "accept":
        return "Say the package they just proposed works for you.";
      case "soft_close":
        // Design §4: near the end of the clock the counterpart steers toward
        // settling on what is on the table. It accepts, and says why now.
        return "Say time is nearly up and that the package they just proposed works for you — better to settle it than run out.";
      case "hold":
        return `Say you can accept most of what they proposed, but you are keeping ${yourRequirement.label.toLowerCase()} where it is for now.`;
      case "concede_trade":
        return `Give a step on ${yourRequirement.label.toLowerCase()} — the term that matters to them, not to you — and put that counteroffer forward.`;
      case "impasse":
        return "Say you do not think you can reach agreement on these terms.";
    }
  })();

  try {
    const { action } = await generateAction({
      kind: "ostensible_human",
      ctx: {
        task,
        agentRole: counterpartRole,
        issues: task.issues,
        stage,
        decidedAction,
      },
      history: body.history ?? [],
    });

    const validation = validateAction(action, {
      issues: task.issues,
      policy: "baseline",
      actorRole: counterpartRole,
    });

    // A blocked action loses its WORDING, not the move behind it — the same
    // rule the proxy route follows, and for the same reason. Returning a 422
    // here left the client with no message and, worse, no package: the
    // counterpart's move for that turn vanished, so the next stage evaluated a
    // stale position. The state machine's decision stands; only the sentence
    // is replaced.
    const blocked =
      !validation.valid && validation.disposition === "regenerate";

    // TODO(supabase): persist `action`, `decision` and `validation` here.
    //
    // WHAT THE CLIENT GETS IS THE MINIMUM IT USES, and that is the rule rather
    // than an optimization. In this condition the counterpart is presented as
    // another Prolific participant, so a participant who opens the network tab
    // and finds `awaitingReason: true` or `action: "concede_distributive"` has
    // learned the other party is machinery — deception rule 1, and the
    // suspicion probe is pilot gate 11.
    //
    // `message` and `proposal` are what the conversation is made of and cannot
    // be withheld. Everything else the state machine decided — whether it
    // accepted, whether this is an impasse, whether it is waiting for a
    // reason, whether the wording was regenerated — stays on the server. The
    // client does not need any of it: it re-runs `counterpartStep` itself for
    // the stage-5 closing test, from the same inputs, and gets the same answer
    // because the machine is deterministic. That is the whole point of the
    // machine owning the decisions.
    return NextResponse.json({
      message: blocked
        ? fallbackText(task, decision.action, decision.proposal)
        : action.rationale,
      proposal: decision.proposal,
    });
  } catch (error) {
    console.error("[counterpart]", error);
    return NextResponse.json(
      { error: "Counterpart generation failed" },
      { status: 500 },
    );
  }
}
